import java.nio.file.*;import java.sql.*;import java.util.*;import com.visioncare.dao.*;
/** Replaces only generated clinical placeholders; never alters money, workflow, accounts or IDs. */
public class RefreshClinicalFixtures {
 static List<String> money(Connection c)throws Exception{List<String> out=new ArrayList<>();String[]qs={"SELECT Invoice_ID,Appointment_ID,Total_Amount,Deposit_Amount,Balance_Due,Status FROM Master_Invoice ORDER BY Invoice_ID","SELECT Transaction_ID,Invoice_ID,Amount,Gateway_Status,Payment_Gateway,Trans_Date FROM Payment_Transaction ORDER BY Transaction_ID","SELECT Appointment_ID,Patient_ID,Schedule_ID,Status,checkin_time,doctor_completed_at FROM Appointment ORDER BY Appointment_ID","SELECT Refund_ID,Invoice_ID,Patient_ID,Refund_Amount,Status FROM Refund_Request ORDER BY Refund_ID"};for(String q:qs)try(Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next()){StringBuilder row=new StringBuilder(q);for(int n=1;n<=r.getMetaData().getColumnCount();n++)row.append('|').append(r.getString(n));out.add(row.toString());}}return out;}
 public static void main(String[]args)throws Exception{if(args.length!=1||!"--apply".equals(args[0]))throw new Exception("Use --apply");
  StringBuilder report=new StringBuilder("# Nội dung bệnh án theo dịch vụ đã có — 26/10/2026\n\nThông tin mô phỏng phục vụ test, không phải kết quả thăm khám thực tế. Chỉ thay nội dung kỹ thuật đã sinh trong 9 ca của An và ca tiểu phẫu của Nam. Không bịa thị lực, nhãn áp hoặc bệnh sử khi DB chưa có.\n\n| APT | Nội dung chẩn đoán | Kết luận |\n|---|---|---|\n");
  try(Connection c=DBContext.getConnection()){if(!"eye_clinic_db".equals(c.getCatalog()))throw new Exception("Wrong DB");c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);try{
   List<String> before=money(c);int patient=SeedUserFlows.id(c,"SELECT p.Patient_ID FROM Patient p JOIN Account ac ON ac.Account_ID=p.Account_ID WHERE ac.Email=? AND ac.Role_ID=6",SeedUserFlows.EMAIL);
   Map<String,Integer> cases=new LinkedHashMap<>();for(String[]def:SeedUserFlows.CASES){int apt=FixtureRegistry.find(c,def[0],patient);if(apt==0)throw new Exception("Missing fixture "+def[0]);cases.put(def[0],apt);}
   // Persist identity before removing legacy clinical markers. Timestamps protect unrelated rows on reruns.
   FixtureRegistry.save(c,cases);
   for(var entry:cases.entrySet()){
    String code=entry.getKey();int apt=entry.getValue();int record=SeedUserFlows.id(c,"SELECT Record_ID FROM Medical_Record WHERE Appointment_ID=?",apt);
    if(code.equals("EXAM_DONE_EXTRAS")){
     if(SeedUserFlows.id(c,"SELECT COUNT(*) FROM Procedure_Order po JOIN Service_Catalog sc ON sc.Service_ID=po.Service_ID WHERE po.Record_ID=? AND sc.Service_Code='TP-LEO' AND po.Status='Completed'",record)!=1)throw new Exception("Procedure source changed");
    }else if(code.equals("EXAM_DONE_BASE")||code.equals("PAID_FINAL")){
     if(SeedUserFlows.id(c,"SELECT COUNT(*) FROM Procedure_Order WHERE Record_ID=? AND Service_ID<>1 AND Status<>'Cancelled'",record)>0)throw new Exception("Additional services now present");
    }
    SeedUserFlows.update(c,"UPDATE Medical_Record SET Clinical_Diagnosis=?,examination_result=?,conclusion=CASE WHEN conclusion=N'Kết thúc khám mẫu; đối chiếu hóa đơn tại quầy' THEN ? WHEN conclusion=N'Yêu cầu hủy lịch: Bận việc cá nhân (ca kiểm thử)' THEN N'Yêu cầu hủy lịch: Bận việc cá nhân, không thể đến khám theo lịch đã đặt' WHEN conclusion=N'Hệ thống: Hết hạn thanh toán (ca kiểm thử)' THEN N'Hệ thống: Hết hạn thanh toán' ELSE conclusion END WHERE Record_ID=? AND Clinical_Diagnosis LIKE ?",ClinicalFixtureText.diagnosis(code),ClinicalFixtureText.result(code),ClinicalFixtureText.conclusion(code),record,SeedUserFlows.marker(code).replace("[","[[]")+"%");
    SeedUserFlows.update(c,"UPDATE Examination_Detail SET Chief_Complaint=?,Medical_History=NULL WHERE Record_ID=? AND Chief_Complaint=N'Ca mô phỏng kiểm thử hóa đơn'",ClinicalFixtureText.complaint(code),record);
    SeedUserFlows.update(c,"UPDATE Procedure_Order SET Referral_Notes=CASE WHEN Referral_Notes=N'Ca mẫu: tiểu phẫu đã thực hiện' THEN N'Chỉ định chích rạch chắp lẹo mi mắt' ELSE Referral_Notes END,Result_Text=CASE WHEN Result_Text=N'Kết quả mô phỏng' THEN N'Đã thực hiện chích rạch chắp lẹo mi mắt' ELSE Result_Text END,Result_Conclusion=CASE WHEN Result_Conclusion=N'Hoàn tất tiểu phẫu mẫu' THEN N'Hoàn tất thủ thuật theo chỉ định' ELSE Result_Conclusion END WHERE Record_ID=?",record);
    SeedUserFlows.update(c,"UPDATE Prescription SET Doctor_Notes=N'Dùng thuốc theo đơn và tái khám theo hướng dẫn của bác sĩ' WHERE Record_ID=? AND Doctor_Notes=N'Đơn mẫu kiểm thử mua thuốc tại quầy'",record);
    SeedUserFlows.update(c,"UPDATE pd SET Dosage_Instruction=N'Dùng theo hướng dẫn trong đơn thuốc' FROM Prescription_Detail pd JOIN Prescription pr ON pr.Prescription_ID=pd.Prescription_ID WHERE pr.Record_ID=? AND pd.Dosage_Instruction=N'Dữ liệu mẫu kiểm thử; không dùng hướng dẫn điều trị'",record);
    SeedUserFlows.update(c,"UPDATE rr SET Reason=N'Đề nghị hoàn phí khám sau khi yêu cầu hủy lịch đã được duyệt trước check-in' FROM Refund_Request rr JOIN Master_Invoice i ON i.Invoice_ID=rr.Invoice_ID WHERE i.Appointment_ID=? AND rr.Reason LIKE ?",apt,SeedUserFlows.marker(code).replace("[","[[]")+"%");
    report.append('|').append(apt).append('|').append(ClinicalFixtureText.diagnosis(code)==null?"Chưa khám: để trống chẩn đoán":ClinicalFixtureText.diagnosis(code)).append('|').append(ClinicalFixtureText.conclusion(code)==null?"Giữ đúng ghi nhận yêu cầu/duyệt hủy nếu có":ClinicalFixtureText.conclusion(code)).append("|\n");
   }
   int nam=SeedUserFlows.id(c,"SELECT mr.Record_ID FROM Medical_Record mr JOIN Appointment a ON a.Appointment_ID=mr.Appointment_ID JOIN Procedure_Order po ON po.Record_ID=mr.Record_ID JOIN Service_Catalog sc ON sc.Service_ID=po.Service_ID WHERE a.Appointment_ID=96 AND mr.Clinical_Diagnosis LIKE N'%DEMO-NAM-20261026%' AND sc.Service_Code='TP-LEO' AND po.Status='Pending'");
   if(nam>0){SeedUserFlows.update(c,"UPDATE Medical_Record SET Clinical_Diagnosis=N'Chắp/lẹo mi mắt; có chỉ định chích rạch.' WHERE Record_ID=?",nam);SeedUserFlows.update(c,"UPDATE Procedure_Order SET Referral_Notes=N'Chỉ định chích rạch chắp lẹo mi mắt, chờ thực hiện thủ thuật.' WHERE Record_ID=? AND Referral_Notes LIKE N'%DỮ LIỆU MẪU%'",nam);}
   if(!before.equals(money(c)))throw new Exception("Financial or workflow data changed");
   c.commit();System.out.println("Updated clinical placeholders for nine An fixtures and the earlier Nam minor-procedure case; no financial/workflow changes.");
  }catch(Exception error){c.rollback();throw error;}}
  report.append("\nMã ca được lưu ở user-flow-registry.properties; không còn dùng chẩn đoán làm nơi chứa mã kỹ thuật. Ca 118 dựa vào TP-LEO đã Completed và thuốc Systane Ultra trong đơn; các ca chỉ có phí khám không bịa thêm bệnh lý. Các ca chưa khám để trống chẩn đoán/kết quả, giữ nguyên ghi nhận hủy lịch cần cho luồng refund.\n");Files.writeString(Path.of("docs/testing/clinical-fixture-content-20261026.md"),report);
 }
}
